INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('cserkelo', 21, '{"id":"cserkelo","nev":"Cserkelő Egyesület","tipus":"Környezetvédelmi és kulturális egyesület","fokategoria":"ceg","logo":{"betu":"CS","szin":"#166534","szoveg":"Cserkelő"},"kepek":[],"visszafizetett":12000000,"visszafizetett_szoveg":"12 000 000 Ft","kapcsolatok":[{"nev":"Tarr Zoltán","szerep":"kulturális miniszter","kepek":["images/tarr-zoltan-kis.jpg"]},{"nev":"Pósfai Gábor","szerep":"belügyminiszter","kepek":["images/posfai-gabor-kis.jpg"]}],"indok":"Természetközeli kulturális események címen elnyert ideiglenes kollégiumi támogatás felülvizsgálat utáni visszatérítése.","kategoriak":["visszafizetes"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('hanko-balazs', 22, '{"id":"hanko-balazs","nev":"Hankó Balázs","tipus":"Volt kulturális és innovációs miniszter, az NKA elnöke","fokategoria":"kozeleti","kepek":["images/hanko-balazs.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"A gyanú szerint 17,3 milliárd Ft eltérített közpénz","kapcsolatok":[{"nev":"Varga-Bajusz Veronika","szerep":"egykori államtitkára, a gyanú szerinti bűntárs – letartóztatásban","kepek":["images/varga-bajusz-veronika-kis.jpg"]},{"nev":"Bús Balázs","szerep":"az NKA alelnöke, szintén őrizetbe vett","kepek":["images/bus-balazs-kis.jpg"]},{"nev":"Tarr Zoltán","szerep":"kulturális miniszter, az ügyet feltáró és elrendelő társa","kepek":["images/tarr-zoltan-kis.jpg"]}],"indok":"Mentelmi jogának felfüggesztése (2026. szept. 28.) után este őrizetbe vették, majd letartóztatták. A gyanú szerint a Kiemelt Kulturális Programok Ideiglenes Kollégiumát miniszterként, az NKA elnökeként vezetőjeként 1079 támogatói okirattal, 17,3 milliárd forintnyi vagyoni hátránnyal tömegesen, a jogszabályi céloktól eltérően – részben fideszes kampányeseményekre, választókerületenként – osztott szét. Letartóztatása jogerős és végleges (Kecskeméti Törvényszék, 2026. okt. 13.).","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('varga-bajusz-veronika', 23, '{"id":"varga-bajusz-veronika","nev":"Varga-Bajusz Veronika","tipus":"Volt államtitkár (KIM) – felsőoktatás, szak- és felnőttképzés, fiatalok","fokategoria":"kozeleti","kepek":["images/varga-bajusz-veronika.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vizsgálat alatt","kapcsolatok":[{"nev":"Hankó Balázs","szerep":"volt minisztere, a gyanú szerinti bűntárs – letartóztatásban","kepek":["images/hanko-balazs-kis.jpg"]}],"indok":"2026. szeptember 28-án Hankó Balázzsal együtt állították elő, október 1-jén a Kecskeméti Járásbíróság letartóztatta – vezetőszáron vitték a tárgyalásra. Október 13-án letartóztatása jogerőssé vált. Különösen jelentős vagyoni hátrányt okozó, bűnszövetségben elkövetett hűtlen kezeléssel gyanúsítják az NKA-ügyben.","kategoriak":["elozetes"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('sesztak-miklos', 24, '{"id":"sesztak-miklos","nev":"Seszták Miklós","tipus":"Volt nemzeti fejlesztési miniszter, országgyűlési képviselő","fokategoria":"kozeleti","kepek":["images/sesztak-miklos.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"A gyanú szerint 12,6 milliárd Ft kenőpénz","kapcsolatok":[{"nev":"Hankó Balázs","szerep":"szintén az NKA-ügyben őrizetbe vett volt miniszter","kepek":["images/hanko-balazs-kis.jpg"]}],"indok":"Mentelmi jogának felfüggesztése után őrizetbe vették az NKA-ügyhöz kapcsolódóan. A gyanú szerint összesen 12,6 milliárd forint értékű kenőpénzt zsebre rakott.","kategoriak":["elozetes"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('bus-balazs', 25, '{"id":"bus-balazs","nev":"Bús Balázs","tipus":"Az NKA volt alelnöke, Óbuda volt fideszes polgármestere","fokategoria":"kozeleti","kepek":["images/bus-balazs.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Lásd: Összefogás Óbudáért Egyesület (20 millió Ft visszafizetve)","kapcsolatok":[{"nev":"Ughy Attila","szerep":"a döntő kollégium vezetője, szintén őrizetbe vett","kepek":["images/ughy-attila-kis.jpg"]},{"nev":"Kiss László","szerep":"Óbuda polgármestere – az óbudai szálak érintettje","kepek":["images/kiss-laszlo-obuda-kis.jpg"]}],"indok":"A botrány kirobbanása után ő volt az első, aki lemondott: az NKA alelnöki posztjáról távozott, majd 2026. június 23-án őrizetbe vették és gyanúsítottként hallgatták ki Kecskeméten. Hűtlen kezeléssel gyanúsítják, védője szerint részletes vallomást tett, letartóztatását kezdeményezték.","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('ughy-attila', 26, '{"id":"ughy-attila","nev":"Ughy Attila","tipus":"A Kiemelt Kulturális Programok Ideiglenes Kollégiumának vezetője, volt fideszes képviselő","fokategoria":"kozeleti","kepek":["images/ughy-attila.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vizsgálat alatt","kapcsolatok":[{"nev":"Hankó Balázs","szerep":"a kollégiumot felügyelő és irányító miniszter","kepek":["images/hanko-balazs-kis.jpg"]},{"nev":"Zámbó Nóra","szerep":"kollégiumi tag, minisztériumi titkárságvezető – szintén őrizetbe vett","kepek":["images/zambo-nora-kis.jpg"]},{"nev":"Burom Gábor","szerep":"kollégiumi tag, kabinetfőnök-helyettes – szintén őrizetbe vett","kepek":["images/burom-gabor-kis.jpg"]}],"indok":"A 17 milliárd forint kiosztásáról döntő ideiglenes kollégium vezetőjeként 2026. június 23-án vették őrizetbe; letartóztatásban maradt. 2010–2019 között a XVIII. kerület polgármestere, korábbi fideszes országgyűlési képviselő volt, a botrány kirobbanása óta (május 6.) nem a Lechner Kft. munkavállalója.","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('krucsaine-herter-aniko', 27, '{"id":"krucsaine-herter-aniko","nev":"Krucsainé Herter Anikó","tipus":"A Nemzeti Kulturális Támogatáskezelő (NKTK) volt főigazgatója","fokategoria":"tisztviselo","kepek":["images/krucsaine-herter.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vizsgálat alatt","kapcsolatok":[{"nev":"Tarr Zoltán","szerep":"kulturális miniszter, aki május 19-én felmentette a posztjáról","kepek":["images/tarr-zoltan-kis.jpg"]},{"nev":"Hankó Balázs","szerep":"a rábízott kifizetések felettese – letartóztatásban","kepek":["images/hanko-balazs-kis.jpg"]}],"indok":"Az NKA-pályázatok lebonyolításával megbízott NKTK főigazgatója volt; Tarr Zoltán 2026. május 19-én mentette fel, június 23-án a NAV őrizetbe vette és gyanúsítottként hallgatta ki. Jogi képviselője később feljelentést tett, mondván: a támogatások egyedi kérelem alapján, szakmai egyeztetés nélkül, a főigazgató személyes utasítására kerültek kifizetésre.","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('burom-gabor', 28, '{"id":"burom-gabor","nev":"Burom Gábor","tipus":"A Kulturális és Innovációs Minisztérium miniszteri kabinetfőnök-helyettese","fokategoria":"tisztviselo","kepek":["images/burom-gabor.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vizsgálat alatt","kapcsolatok":[{"nev":"Hankó Balázs","szerep":"a miniszter, akinek a kabinetjében dolgozott – letartóztatásban","kepek":["images/hanko-balazs-kis.jpg"]},{"nev":"Ughy Attila","szerep":"a kollégium vezetője, szintén őrizetbe vett","kepek":["images/ughy-attila-kis.jpg"]}],"indok":"A 17 milliárd forint kiosztásáról döntő Kiemelt Kulturális Programok Ideiglenes Kollégiumának tagja; 2026. június 23-án a NAV őrizetbe vette és hűtlen kezelés gyanújával hallgatta ki a minisztériumban tartott kutatásokat követően.","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('zambo-nora', 29, '{"id":"zambo-nora","nev":"Zámbó Nóra","tipus":"A KIM Közigazgatási Államtitkári Titkárságának főosztályvezetője, titkárságvezetője","fokategoria":"tisztviselo","kepek":["images/zambo-nora.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vizsgálat alatt","kapcsolatok":[{"nev":"Ughy Attila","szerep":"a kollégium vezetője, szintén őrizetbe vett","kepek":["images/ughy-attila-kis.jpg"]},{"nev":"Hankó Balázs","szerep":"volt miniszter – letartóztatásban","kepek":["images/hanko-balazs-kis.jpg"]}],"indok":"A minisztériumi közigazgatási államtitkárságról a döntőbizottsági tagként került a Kiemelt Kulturális Programok Ideiglenes Kollégiumába; a NAV 2026. június 23-án őt is őrizetbe vette és gyanúsítottként hallgatta ki a 17 milliárdos NKA-ügyben.","kategoriak":["elozetes","felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('nktk-hatteremberek', 30, '{"id":"nktk-hatteremberek","nev":"NKTK-s és minisztériumi háttéremberek (több személy)","tipus":"Kormányzati alkalmazottak és cégvezetők – a döntések kevésbé ismert végrehajtói","fokategoria":"tisztviselo","logo":{"betu":"NK","szin":"#475569","szoveg":"NKTK / KIM"},"kepek":[],"visszafizetett":null,"visszafizetett_szoveg":"A hatóságok vizsgálják","kapcsolatok":[{"nev":"Papp Gergely","szerep":"NKTK-projektmenedzser – ő szivárogtatta ki a 17 milliárdos nem nyilvános keretet Molnár Áronnak; ezután őt és környezetét indoklás nélkül kizárták a belső rendszerekből","kepek":["images/papp-gergely-kis.png"]},{"nev":"Krucsainé Herter Anikó","szerep":"a volt főigazgató – szintén őrizetbe vett","kepek":["images/krucsaine-herter-kis.jpg"]}],"indok":"Az NKTK és a KIM egykori és jelenlegi alkalmazottai, akiket a NAV őrizetbe vett: egy részük neve a szélesebb nyilvánosság számára kevésbé ismert. 2026. szeptember 7-én újabb két személyt állítottak elő egy 80 millió forint feletti, el sem készült dokumentumfilm fiktív számlákkal leplezett elszámolása miatt. Szeptember közepén összesen négyen voltak letartóztatásban, öten bűnügyi felügyelet alatt; a gyanúsítottak között volt olyan, aki ma is az NKTK alkalmazásában áll.","kategoriak":["elozetes"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('balasy-gyula', 31, '{"id":"balasy-gyula","nev":"Balásy Gyula","tipus":"Médiavállalkozó – a NER egykori kedvence, a Lounge-csoport tulajdonosa","fokategoria":"kozeleti","kepek":["images/balasy-gyula.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Cégeit ingyen átadta az államnak (~80 Mrd Ft értékben)","kapcsolatok":[{"nev":"Ruszin-Szendi Romulusz","szerep":"honvédelmi miniszter – feljelentést tett ellene","kepek":["images/ruszin-szendi-kis.jpg"]},{"nev":"Nemzeti Kommunikációs Hivatal","szerep":"a korábbi 300+ milliárdos közbeszerzések gazdája","kepek":[]}],"indok":"2026 májusában közjegyző előtt aláírt okiratban lemondott négy cége (Lounge Design, Lounge Event, New Land Media, Visual Europe) üzletrészeiről, és felajánlotta azokat – értéküket kb. 80 milliárd forintra becsülve –, valamint magántőkealap-befektetéseit az államnak, miután bankszámláikat zárolták. A cégek ellen büntetőeljárás és végrehajtás indult, a Miniszterelnökség, a közmédia és a Nemzeti Rendezvényszervező Ügynökség is felmondta a szerződéseit; a CRCB elemzése szerint 2011 óta ~1135 milliárd forintnyi közpénzhez jutottak.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('szijjarto-peter', 32, '{"id":"szijjarto-peter","nev":"Szijjártó Péter","tipus":"Volt külgazdasági és külügyminiszter, jelenleg a BYD-nál","fokategoria":"kozeleti","kepek":["images/szijjarto-peter.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Büntetőfeljelentés – kb. 1 millió eurós kár","kapcsolatok":[{"nev":"Külgazdasági és Külügyminisztérium","szerep":"a belső audit, amely feltárta a repülőgép-bérlési gyakorlatot","kepek":[]}],"indok":"A Külgazdasági és Külügyminisztérium belső auditja után hivatalos büntetőfeljelentés született a tárca korábbi magánrepülőgép-bérlési gyakorlata miatt (feleslegesen kifizetett luxusutak, kb. 1 millió eurós kár). Az eljárás folyik, előzetesben nincs; ő jelenleg a versenyszférában, a BYD-nál dolgozik.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('matolcsy-gyorgy', 33, '{"id":"matolcsy-gyorgy","nev":"Matolcsy György","tipus":"A Magyar Nemzeti Bank volt elnöke","fokategoria":"kozeleti","kepek":["images/matolcsy-gyorgy.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Elszámoltatás előkészítése alatt","kapcsolatok":[{"nev":"Matolcsy Ádám","szerep":"fia – külön kártyán szerepel","kepek":["images/matolcsy-adam-kis.jpg"]},{"nev":"Országgyűlési vizsgálóbizottság","szerep":"őt is meghallgatná az MNB-ügyben","kepek":[]}],"indok":"Az MNB-ügyeket és a jegybanki alapítványok kifizetéseit vizsgáló parlamenti bizottság hivatalosan is beidézheti elszámoltatásra. Szerinte az alapítványi vagyon nem tűnt el, csak „csalóka a tőzsdei értéke”. Az eljárás előkészítése folyik, előzetes letartóztatása nincs; a KNYF nyomozása egyelőre gyanúsított nélkül zajlik.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('matolcsy-adam', 34, '{"id":"matolcsy-adam","nev":"Matolcsy Ádám","tipus":"A volt jegybankelnök fia – üzletember, Dubaj","fokategoria":"kozeleti","kepek":["images/matolcsy-adam.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Nyomoznak az ügyében – gyanúsított még nincs","kapcsolatok":[{"nev":"Matolcsy György","szerep":"édesapja, a volt MNB-elnök","kepek":["images/matolcsy-gyorgy-kis.jpg"]},{"nev":"Somlai Bálint","szerep":"üzlettárs – az elveszett pénzek egyik kulcsfigurája","kepek":["images/somlai-balint-kis.jpg"]},{"nev":"Központi Nyomozó Főügyészség","szerep":"a Matolcsy-körnél házkutatást tartó nyomozóhatóság","kepek":["images/kozponti-nyomozo-fougyeszseg-kis.jpg"]}],"indok":"A jegybanki alapítványok (PADME) 266+127,5 milliárd forintjának ügyében több mint másfél éve folyik nyomozás különösen jelentős vagyoni hátrányt okozó hűtlen kezelés miatt. 2026. szeptember 22-én a KNYF házkutatást és lefoglalást tartott a Matolcsy-körnél – gyanúsítotti kihallgatás eddig nem volt. Az ügyben 97 magánszemély, 36 cég és 11 magántőkealap érintett, 91,8 milliárd forintnyi készpénz és értékpapír került biztosítás alá. Ádám luxus életmódjáról ismert, dubaji cégéhez került a Vörösmarty téri ingatlan, 2025-ben holdingja 407 milliós nyereséget és 36,6 milliárdos eszközállományt mutatott ki; állítása szerint bevételei legálisak, tartózkodási engedéllyel él az Egyesült Arab Emírségekben, és kész együttműködni a hatóságokkal.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('szakacs-istvan', 35, '{"id":"szakacs-istvan","nev":"Szakács István","tipus":"Fidesz-közeli (megafonos) influenszer","fokategoria":"maganszemely","kepek":["images/szakacs-istvan.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Nyomozás megszüntetve (bizonyítottság hiányában)","kapcsolatok":[{"nev":"Nemzeti Nyomozó Iroda","szerep":"a nyomozást megszüntető hatóság","kepek":[]}],"indok":"2026 júliusában terrorcselekmény elkövetésével fenyegetés gyanújával hallgatták ki és bilincsben vitték be, miután egy videóban Orbán Viktor esetleges elviteléről és kiszabadításáról beszélt. A Nemzeti Nyomozó Iroda október 16-án bizonyítottság hiányában megszüntette ellene a nyomozást; az ügyészség a feljelentő panaszát is elutasította.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('furcht-pal', 36, '{"id":"furcht-pal","nev":"Dr. Fürcht Pál","tipus":"Volt főügyész, a Központi Nyomozó Főügyészség (KNYF) korábbi vezetője","fokategoria":"tisztviselo","kepek":["images/furcht-pal.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Felmentve – most inkább tanúskodik","indok":"2026 júniusban lemondott a Központi Nyomozó Főügyészség éléről. Október elején Magyar Péter miniszterelnök nyilvánosan számon kérte rajta a 2024-es ügyészi intézkedéseket: szerinte Fürcht Rogán Antalt tisztázta a Völner–Schadl-ügyben, és egy hajléktalanszállásos incidensből próbált súlyosabb bűncselekményt kreálni, hogy ellehetetlenítse a választási indulást. Meg is gyanúsították azzal, hogy Rogán Antalékat kivágta a nyomozati ügyekből – ebből azonban felmentették, így most már inkább tanúskodik: október 12-én bejelentette, kész részletes vallomást tenni a Rogán–Schadl–Völner-ügyben és az iratok átírására tett kísérletekről, október 18-án pedig soron kívül hallgatják meg. Az ügyészség eközben október 15-én felfüggesztette ügyészi állásából, és fegyelmi eljárást indított ellene, mert „egyoldalú értelmezéssel” hozott nyilvánosságra információkat egy folyamatban lévő büntetőügyben.","kapcsolatok":[{"nev":"Rogán Antal","szerep":"kabinetminiszter – őt „vágta ki” az ügyekből (állítólag)","kepek":["images/rogan-antal-kis.jpg"]},{"nev":"Magyar Péter","szerep":"miniszterelnök – ő állította ki a szorítóból","kepek":["images/magyar-peter-kis.jpg"]},{"nev":"Lajtár István","szerep":"legfőbb ügyész-helyettes – felfüggesztette és fegyelmit indított","kepek":["images/lajtar-istvan-kis.jpg"]}],"kategoriak":["tanu"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('toth-gabi', 37, '{"id":"toth-gabi","nev":"Tóth Gabi","tipus":"Énekesnő, előadóművész","fokategoria":"maganszemely","kepek":["images/toth-gabi.jpg"],"visszafizetett":null,"osszeg_cimke":"Kapott összeg","visszafizetett_szoveg":"5 000 000 Ft + cége 9 000 000 Ft","kapcsolatok":[{"nev":"Tóth Gabi","szerep":"pályázó magánszemély","kepek":["images/toth-gabi-kis.jpg"]},{"nev":"Tóth Gabi és párja közös cége","szerep":"a 9 milliós támogatás kedvezményezettje","kepek":[]}],"indok":"A Fidesz kampányában fellépő előadóművészek között ő is az NKA kiemelt keretéből kapott: magánszemélyként 5 milliót, a párjával közös cégén keresztül további 9 milliót. Egyike a legtöbbet emlegetett kedvezményezetteknek, pénzt eddig nem adott vissza.","kategoriak":["kapta"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('dopeman', 38, '{"id":"dopeman","nev":"Dopeman (Pityinger László)","tipus":"Rapper, előadóművész","fokategoria":"maganszemely","kepek":["images/dopeman.jpg"],"visszafizetett":null,"osszeg_cimke":"Kapott összeg","visszafizetett_szoveg":"5 000 000 Ft","kapcsolatok":[{"nev":"Dopeman","szerep":"pályázó","kepek":["images/dopeman-kis.jpg"]},{"nev":"Hankó Balázs","szerep":"a kereteket osztó volt miniszter – letartóztatásban","kepek":["images/hanko-balazs-kis.jpg"]}],"indok":"Könnyűzenei támogatásként 5 millió forintot kapott az NKA ideiglenes kollégiumi keretéből. Visszafizetni eddig nem fizetett, a NAV nyomozásba egyelőre nem vonták be.","kategoriak":["kapta"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('deak-bill-gyula', 39, '{"id":"deak-bill-gyula","nev":"Deák Bill Gyula","tipus":"Énekes, előadóművész (Kossuth-díjas)","fokategoria":"maganszemely","kepek":["images/deak-bill-gyula.jpg"],"visszafizetett":null,"osszeg_cimke":"Kapott összeg","visszafizetett_szoveg":"100 000 000 Ft","kapcsolatok":[{"nev":"Deák Bill Gyula","szerep":"kedvezményezett","kepek":["images/deak-bill-gyula-kis.jpg"]},{"nev":"Balásy Gyula","szerep":"a cégháló középpontjában – cégeit átadta az államnak","kepek":["images/balasy-gyula-kis.jpg"]}],"indok":"A „legenda nemzeti turné” elnevezésű projekt kapott 100 millió forintot. Az összeg a Balásy Gyula érdekeltségébe tartozó cégeken keresztül csorgott, a NAV a turné számláit is vizsgálja; a pénzt eddig nem adta vissza.","kategoriak":["kapta"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('pataky-attila', 40, '{"id":"pataky-attila","nev":"Pataky Attila és cége","tipus":"Énekes, előadóművész / vállalkozás","fokategoria":"maganszemely","kepek":["images/pataky-attila.jpg"],"visszafizetett":null,"osszeg_cimke":"Kapott összeg","visszafizetett_szoveg":"150 000 000 Ft (cégen keresztül)","kapcsolatok":[{"nev":"Pataky Attila","szerep":"előadóművész, a cége tulajdonosa","kepek":["images/pataky-attila-kis.jpg"]},{"nev":"Mága Zoltán hivatalos fotósának cége","szerep":"szintén kedvezményezett – 500 millióval","kepek":[]}],"indok":"Az előadó érdekeltségébe tartozó cég 150 millió forintos támogatást kapott az NKA-tól. Az összeg nagyságrendje a közvéleményben a leginkább kifogásolt tételek közé tartozik; visszafizetés nem történt.","kategoriak":["kapta"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('maga-foto-ceg', 41, '{"id":"maga-foto-ceg","nev":"Mága Zoltán hivatalos fotósának cége","tipus":"Cég (a fotós neve nem nyilvános)","fokategoria":"ceg","kepek":[],"logo":{"betu":"MF","szin":"#7c3aed","szoveg":"Mága Zoltán hivatalos fotósának cége"},"visszafizetett":null,"osszeg_cimke":"Kapott összeg","visszafizetett_szoveg":"500 000 000 Ft","kapcsolatok":[{"nev":"Mága Zoltán","szerep":"hegedűművész, aki a fotósa fellépésein kíséri","kepek":["images/maga-zoltan-kis.jpg"]},{"nev":"Balásy Gyula","szerep":"a céghálóban szereplő rendezvényszervező","kepek":["images/balasy-gyula-kis.jpg"]}],"indok":"Fél milliárd forintot kapott az NKA-tól egy olyan cég, amely Mága Zoltán hivatalos fotósának a nevén volt bejegyezve – a támogatás célja „kulturális tartalomgyártás” volt. Az összeg a Balásy-birodalomhoz köthető számlázási lánc részeként jelent meg; a pénz nem került vissza.","kategoriak":["kapta"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('torok-ignac-alapitvany', 42, '{"id":"torok-ignac-alapitvany","nev":"Török Ignác Gimnáziumért Alapítvány","tipus":"Alapítvány (Győr)","fokategoria":"ceg","kepek":[],"logo":{"betu":"TI","szin":"#0f766e","szoveg":"Török Ignác Gimnáziumért Alapítvány"},"visszafizetett":9000,"visszafizetett_szoveg":"9 000 Ft","kapcsolatok":[{"nev":"Török Ignác Gimnáziumért Alapítvány","szerep":"kedvezményezett","kepek":[]}],"indok":"A Jókai 200-hoz kapcsolódó Jókai-konferenciára kért támogatást. A visszafizetési lista legkisebb tétele: 9 000 forint – ennyi is visszakerült az államkasszába.","kategoriak":["visszafizetes"]}');
