INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('bekes-vill', 45, '{"id":"bekes-vill","nev":"Békés-VILL Kft.","tipus":"Cég – villanyszerelés, generálkivitelezés","fokategoria":"ceg","kepek":[],"logo":{"betu":"BV","szin":"#ca8a04","szoveg":"Békés-VILL Kft."},"visszafizetett":19500000,"visszafizetett_szoveg":"19 500 000 Ft","kapcsolatok":[{"nev":"Békés-VILL Kft.","szerep":"kedvezményezett","kepek":[]}],"indok":"„A főtevékenységünk a villanyszerelés” – mégis kulturális programokra kért majd 20 milliót az NKA-tól, amit végül visszafizetett. Az egyik legékesebb példa arra, kihez is ment a pénz.","kategoriak":["visszafizetes"]}');
