INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('simonka-gyorgy', 49, '{"id":"simonka-gyorgy","nev":"Simonka György","tipus":"Volt fideszes országgyűlési képviselő","fokategoria":"kozeleti","kepek":["images/simonka-gyorgy.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 75/100 kockázati index","kapcsolatok":[],"indok":"Bűnszervezetben elkövetett, különösen jelentős költségvetési csalással vádolják; az ellene folyó büntetőperben a bíróság másodszor is nekifutott az ügynek. Az Út a börtönbe rangsorában 75/100-as indexszel a legmagasabb kockázatú szereplő, vádemelés közelinek minősítve.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('czegledy-csaba', 50, '{"id":"czegledy-csaba","nev":"Czeglédy Csaba","tipus":"Ügyvéd, a DK-hoz kötődő ellenzéki közszereplő","fokategoria":"kozeleti","kepek":["images/czegledy-csaba.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 72/100 kockázati index","kapcsolatok":[],"indok":"Ügyvéd, a DK-hoz kötődő ellenzéki közszereplő, korábbi önkormányzati képviselő. Az ellene folyó büntetőügyben első fokon hétéves fegyházbüntetést kapott, a fellebbviteli szakaszban az ügyészség a hét évnél szigorúbb ítéletet kért; szabadlábon védekezhet. Az Út a börtönbe rangsorában 72/100.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('boldog-istvan', 51, '{"id":"boldog-istvan","nev":"Boldog István","tipus":"Volt fideszes országgyűlési képviselő","fokategoria":"kozeleti","kepek":["images/boldog-istvan.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 71/100 kockázati index","kapcsolatok":[],"indok":"Volt fideszes országgyűlési képviselő, korrupciós pere folyamatban van; a perben kiderült, hogy az ügyészség három hónapnyi lehallgatási anyagot nem archivált („adminisztrációs hiba”). Az Út a börtönbe rangsorában 71/100, vádemelés közel.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('hidvegi-jozsef', 52, '{"id":"hidvegi-jozsef","nev":"Hidvégi József","tipus":"Fonyód volt fideszes polgármestere","fokategoria":"kozeleti","kepek":["images/hidvegi-jozsef.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 70/100 kockázati index","kapcsolatok":[],"indok":"Fonyód volt fideszes polgármestere (2019–2024). Gazdasági csalás és pénzmosás gyanújával harminc napra letartóztatták. Az Út a börtönbe rangsorában 70/100, vádemelés közel.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('biro-ferenc', 53, '{"id":"biro-ferenc","nev":"Bíró Ferenc","tipus":"Az Integritás Hatóság elnöke","fokategoria":"kozeleti","kepek":["images/biro-ferenc.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 68/100 kockázati index","kapcsolatok":[],"indok":"Az Integritás Hatóság elnöke; ellene vádat emeltek, a vádiratban letöltendő szabadságvesztést kértek. Az Út a börtönbe rangsorában 68/100, vádemelés közel.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('schadl-gyorgy', 54, '{"id":"schadl-gyorgy","nev":"Schadl György","tipus":"A Magyar Bírósági Végrehajtói Kar volt elnöke","fokategoria":"kozeleti","kepek":[],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 65/100 kockázati index","kapcsolatok":[],"indok":"A Magyar Bírósági Végrehajtói Kar volt elnöke, a Schadl–Völner-per elsőrendű vádlottja. A vád szerint az államtitkár üzenetét vitte a végrehajtói kinevezésekről, a perben pedig egy végrehajtó arról vallott, hogyan vette fel neki a pénzt. Az Út a börtönbe rangsorában 65/100, vádemelés közel.","kategoriak":["felkeszul"]}');
INSERT OR REPLACE INTO bejegyzesek (id, sorrend, adat) VALUES ('volner-pal', 55, '{"id":"volner-pal","nev":"Völner Pál","tipus":"Volt igazságügyi államtitkár, ügyvéd","fokategoria":"kozeleti","kepek":["images/volner-pal.jpg"],"visszafizetett":null,"visszafizetett_szoveg":"Vádemelés közel – 65/100 kockázati index","kapcsolatok":[],"indok":"Volt igazságügyi államtitkár, a Schadl–Völner-per másodrendű vádlottja; hiába a vád, ügyvédként újra praktizálhat. Az Út a börtönbe rangsorában 65/100, vádemelés közel.","kategoriak":["felkeszul"]}');
